cat > /app/witness_povray_v2.sh <<'WEOF'
#!/bin/bash
# Witness v2: POV-Ray 2.2 builds from source and renders illum1.pov.
set -e
BUILD=/app/povray-2.2/build
INC=/app/povray-2.2/povdoc/include

# Deliverable must exist at all (baseline 37c0a03 has no povray-2.2).
[ -f "$BUILD/unix.c" ] || { echo "FAIL: build tree missing"; exit 1; }
[ -f "$BUILD/config.h" ] || { echo "FAIL: config.h missing"; exit 1; }

# Porting edits must be present (original source lacks them).
grep -q 'MAIN_RETURN_TYPE int' "$BUILD/config.h" || { echo "FAIL: no MAIN_RETURN_TYPE int"; exit 1; }
grep -q '#include <stdlib.h>' "$BUILD/config.h" || { echo "FAIL: no stdlib include"; exit 1; }
! grep -q 'libm_exception' "$BUILD/unix.c" || { echo "FAIL: libm_exception still present"; exit 1; }

# Rebuild from source.
cd "$BUILD" && rm -f *.o povray && make CC=gcc >/dev/null 2>&1

# Sanity check: the binary must render illum1.pov with statistics.
./povray +L"$INC" +I/app/deps/illum1.pov +O/dev/null +P -V >/tmp/povv2.txt 2>&1
grep -q "illum1.pov statistics" /tmp/povv2.txt || { echo "FAIL: no stats"; exit 1; }
grep -q "Resolution 100 x 100" /tmp/povv2.txt || { echo "FAIL: no resolution"; exit 1; }

# Valid TGA render (the form a reference-image comparison consumes).
./povray +L"$INC" +I/app/deps/illum1.pov +O/tmp/povv2.tga +FT +W160 +H120 -D -V >/dev/null 2>&1
sz=$(stat -c%s /tmp/povv2.tga)
[ "$sz" -eq 57618 ] || { echo "FAIL: tga size $sz"; exit 1; }
typ=$(od -An -tu1 -j2 -N1 /tmp/povv2.tga | tr -d ' ')
[ "$typ" -eq 2 ] || { echo "FAIL: tga type $typ"; exit 1; }

echo "WITNESS V2 PASSED"
WEOF
chmod +x /app/witness_povray_v2.sh
# Quick self-check
bash /app/witness_povray_v2.sh 2>&1; echo "=== self exit: $? ==="
